const rows = $input.all().map(i => { const f = i.json.fields || i.json; return { id: i.json.id, ...f }; });
const today = new Date().toISOString().slice(0, 10);
const countBy = (field) => { const m = {}; for (const r of rows) { const v = r[field] || 'unknown'; m[v] = (m[v] || 0) + 1; } return m; };
const temperature = countBy('temperature');
const qualification_status = countBy('qualification_status');
const crm_sync_status = countBy('crm_sync_status');
const failures = rows.filter(r => r.crm_sync_status === 'failed').length;
const dueFollowUps = rows.filter(r => r.follow_up_at && String(r.follow_up_at).slice(0, 10) <= today).length;
const total = rows.length;
return [{ json: { total, temperature, qualification_status, crm_sync_status, failures, due_follow_ups: dueFollowUps, generated_at: new Date().toISOString() } }];

const agg = $('Aggregate Pipeline').item.json;
const ai = $input.first().json;
const narrative = (ai && (ai.text || ai.output || (ai.json && ai.json.text))) || '';
const lines = [];
lines.push('Weekly Pipeline Report — Northstar Growth Studio');
lines.push('Generated: ' + agg.generated_at);
lines.push('');
lines.push('TOTAL LEADS: ' + agg.total);
lines.push('By temperature: ' + JSON.stringify(agg.temperature));
lines.push('By qualification_status: ' + JSON.stringify(agg.qualification_status));
lines.push('By crm_sync_status: ' + JSON.stringify(agg.crm_sync_status));
lines.push('CRM sync failures: ' + agg.failures);
lines.push('Due follow-ups: ' + agg.due_follow_ups);
lines.push('');
lines.push('Narrative:');
lines.push(narrative || '(AI summary unavailable; aggregates above are authoritative.)');
return [{ json: { report_text: lines.join('\n'), aggregates: agg, narrative } }];
